<?php
require_once __DIR__ . '/../../includes/auth.php'; require_role('admin');
$userId = filter_input(INPUT_GET, 'id', FILTER_VALIDATE_INT); if (!$userId || $userId < 1) { flash_set('error', 'Invalid user ID specified.'); redirect('modules/users/index.php'); }
try { $stmt = $conn->prepare('SELECT user_id, username, email, full_name, role, is_active FROM users WHERE user_id = ? LIMIT 1'); if (!$stmt) throw new RuntimeException($conn->error); $stmt->bind_param('i', $userId); $stmt->execute(); $user = $stmt->get_result()->fetch_assoc(); $stmt->close(); if (!$user) { flash_set('error', 'User record not found.'); redirect('modules/users/index.php'); } } catch (Throwable $e) { error_log('Database exception loading user for edit: ' . $e->getMessage()); flash_set('error', 'A database error occurred while retrieving the user.'); redirect('modules/users/index.php'); }
$pageTitle = 'Edit User'; $currentNav = 'users'; $errors = $_SESSION['_form_errors'] ?? []; $old = $_SESSION['_form_old'] ?? []; unset($_SESSION['_form_errors'], $_SESSION['_form_old']); $selectedRole = $old['role'] ?? $user['role']; $selectedStatus = $old['is_active'] ?? (string)$user['is_active'];
include __DIR__ . '/../../includes/header.php'; include __DIR__ . '/../../includes/sidebar.php';
?>
<div class="page-header"><div class="page-title-group"><h1>Edit User</h1><div class="page-subtitle"><?= e($user['full_name']) ?> &bull; <?= e($user['username']) ?></div></div><div class="page-actions"><a href="<?= e(url('modules/users/view.php?id=' . (int)$user['user_id'])) ?>" class="btn btn-secondary">View Profile</a><a href="<?= e(url('modules/users/index.php')) ?>" class="btn btn-secondary">Back to List</a></div></div>
<div class="card card-form"><div class="card-header"><h2>Role and Account Status</h2></div><div class="card-body"><form action="<?= e(url('modules/users/update.php')) ?>" method="post" novalidate><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= (int)$user['user_id'] ?>">
<div class="form-group"><label class="form-label">Full Name</label><div><?= e($user['full_name']) ?></div></div><div class="form-group"><label class="form-label">Username</label><div><?= e($user['username']) ?></div></div><div class="form-group"><label class="form-label">Email</label><div><?= e($user['email']) ?></div></div>
<div class="form-group"><label for="role" class="form-label">Role <span class="required">*</span></label><select id="role" name="role" class="form-control <?= isset($errors['role']) ? 'has-error' : '' ?>" required><?php foreach (ROLES_LIST as $role): ?><option value="<?= e($role) ?>" <?= $selectedRole === $role ? 'selected' : '' ?>><?= e(ucwords(str_replace('_', ' ', $role))) ?></option><?php endforeach; ?></select><?php if (isset($errors['role'])): ?><span class="form-error"><?= e($errors['role']) ?></span><?php endif; ?></div>
<div class="form-group"><label for="is_active" class="form-label">Status <span class="required">*</span></label><select id="is_active" name="is_active" class="form-control <?= isset($errors['is_active']) ? 'has-error' : '' ?>" required><option value="1" <?= $selectedStatus === '1' ? 'selected' : '' ?>>Active</option><option value="0" <?= $selectedStatus === '0' ? 'selected' : '' ?>>Inactive</option></select><?php if (isset($errors['is_active'])): ?><span class="form-error"><?= e($errors['is_active']) ?></span><?php endif; ?></div>
<?php if ((int)$user['user_id'] === (int)($_SESSION['user_id'] ?? 0)): ?><p class="form-text">Your own account must remain active and retain the Admin role.</p><?php endif; ?><div class="form-actions"><button type="submit" class="btn btn-primary">Save Changes</button><a href="<?= e(url('modules/users/view.php?id=' . (int)$user['user_id'])) ?>" class="btn btn-secondary">Cancel</a></div></form></div></div>
